llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Hydrocortisone absolute oral bioavailability was 0.95 in healthy adults; as a high-transfer steroid-like analogue, this directly supports F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Finasteride absolute oral bioavailability was 63% (range 34-108%) in healthy volunteers; its fused polycyclic steroid-like scaffold and tert-butyl group are relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C82"],
      "claim": "Methylprednisolone oral suspension systemic bioavailability was 58.26 ± 14.44% versus IV; another corticosteroid analogue supports high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ixabepilone absolute oral bioavailability was 41.3% (geometric mean) across doses; a complex lipophilic natural product with poor aqueous solubility still exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Clavulanic acid absolute bioavailability was 60.0 ± 23.1% in volunteers; a small fused bicyclic lactone-containing scaffold supports that lactone-rich molecules can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Morphine absolute oral bioavailability was 24% in humans; even a high-first-pass opioid remains above the 20% threshold, supporting the threshold decision.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Naltrexone oral bioavailability was about 5-10% in patients; this is the clearest low-F evidence, but its basic morphinan structure and lower transfer score limit relevance to the neutral lactone-rich query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polycyclic, lipophilic lactone terpenoid. High-transfer steroid-like analogues (hydrocortisone, finasteride, methylprednisolone) consistently show absolute oral F > 50%, and other complex natural products (ixabepilone, clavulanate, morphine) exceed the 20% threshold. The only clearly low-F analogue, naltrexone, has lower transferability and a structurally dissimilar basic morphinan scaffold. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No data on query-specific intestinal permeability, first-pass esterase/lactone hydrolysis, or transporter-mediated efflux.",
    "Formulation dependence of oral bioavailability is not addressed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

